function renderMermaidTimeline(root,data) {
 const scene=root.querySelector('.scene'),viewport=root.querySelector('.diagram-scroll'),svg=scene.querySelector('svg');
 root.classList.add('qv-timeline');root.dataset.state='enhanced';root.dataset.renderer='qv-timeline';root.querySelector('.edge-key').hidden=true;viewport.setAttribute('aria-label','按源码顺序排列的时间轴，可横向滚动');
 if(data.title&&root.querySelector('h3').hidden){root.querySelector('h3').textContent=data.title;root.querySelector('h3').hidden=false;}
 const style=document.createElement('style');style.textContent=`
 #${root.id} .timeline-column{position:absolute;width:216px;top:42px;box-sizing:border-box;padding:12px;border-radius:12px;background:transparent}
 #${root.id} .timeline-period{display:block;width:100%;min-height:38px;border:0;background:none;text-align:left;font:inherit;font-size:13px;font-weight:500;color:var(--foreground);padding:0 0 10px;line-height:20px;white-space:normal;overflow-wrap:anywhere;cursor:var(--cursor-interaction,pointer)}
 #${root.id} .timeline-events{margin-top:38px;padding-left:22px;display:flex;flex-direction:column;gap:12px}
 #${root.id} .timeline-event{display:block;width:100%;box-sizing:border-box;border:0;border-radius:4px;background:transparent;color:var(--foreground);text-align:left;font:inherit;font-size:14px;line-height:22px;min-height:30px;padding:4px 0;white-space:normal;overflow-wrap:anywhere;cursor:var(--cursor-interaction,pointer)}
 #${root.id} .timeline-event[data-active=true],#${root.id} .timeline-event:focus-visible{color:var(--viz-series-1);outline:none}
 #${root.id} .timeline-event:focus-visible{outline:1px solid var(--viz-series-1);outline-offset:4px}
 #${root.id} .timeline-event-point{fill:var(--timeline-tone);stroke:var(--background);stroke-width:3}
 #${root.id} .timeline-section{position:absolute;top:0;font-size:12px;line-height:20px;color:color-mix(in srgb,var(--timeline-tone) 55%,var(--foreground))}
 #${root.id} .timeline-section>span{position:sticky;left:0;display:inline-block;box-sizing:border-box;max-width:100%;padding:4px 10px;border-radius:999px;background:color-mix(in srgb,var(--timeline-tone) 15%,var(--background));overflow-wrap:anywhere}
 #${root.id} .wires{z-index:1}
 #${root.id} .timeline-axis,#${root.id} .timeline-stem{stroke:var(--border);stroke-width:1;fill:none}
 #${root.id} .timeline-point{fill:var(--timeline-tone);stroke:var(--background);stroke-width:2}

 `;root.append(style);
 const NS='http://www.w3.org/2000/svg',el=(tag,attrs)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);svg.append(n);return n;};
 const tones=[3,6,2,1,4,5],groups=[...new Set(data.tasks.map(t=>t.section))],tone=section=>`var(--viz-series-${tones[groups.indexOf(section)%tones.length]})`;let gap=40,w=216;const left=24,width=left*2+data.tasks.length*(w+gap)-gap,objects=[];scene.style.width=width+'px';scene.style.minWidth=width+'px';
 let lastSection=null,sectionStart=0;data.tasks.forEach((t,i)=>{if(t.section!==lastSection){if(lastSection)renderSection(lastSection,sectionStart,i);lastSection=t.section;sectionStart=i;}if(i===data.tasks.length-1&&lastSection)renderSection(lastSection,sectionStart,i+1);});
 function renderSection(name,start,end){const n=document.createElement('div');n.className='timeline-section';n.style.setProperty('--timeline-tone',tone(name));const caption=document.createElement('span');caption.textContent=name;n.append(caption);n.dataset.sectionStart=left+start*(w+gap);n.dataset.sectionIndex=start;n.dataset.sectionCount=end-start;n.style.left=left+start*(w+gap)+'px';n.style.width=(end-start)*(w+gap)-gap+'px';scene.append(n);}
 const fadeId=root.id+'-timeline-tail',defs=el('defs',{}),fade=el('linearGradient',{id:fadeId,gradientUnits:'userSpaceOnUse'});defs.append(fade);[1,0].forEach((opacity,i)=>{const stop=el('stop',{offset:i?'100%':'0%','stop-opacity':opacity,style:'stop-color:var(--border)'});fade.append(stop);});
 const axis=el('path',{class:'timeline-axis',d:`M${left} 96H${left+(data.tasks.length-1)*(w+gap)}`});
 const tail=el('path',{class:'timeline-tail',fill:'none','stroke-width':1,stroke:`url(#${fadeId})`});
 data.tasks.forEach((t,i)=>{const x=left+i*(w+gap),column=document.createElement('div');column.className='timeline-column';column.dataset.period=t.id;column.style.setProperty('--timeline-tone',tone(t.section));column.style.left=x+'px';const b=document.createElement('button');b.type='button';b.className='timeline-period';b.textContent=t.name;column.append(b);const content=document.createElement('div');content.className='timeline-events';column.append(content);if(t.description){const d=document.createElement('div');d.className='timeline-description';d.textContent=t.description;d.style.cssText='font-size:12px;line-height:18px;color:var(--muted-foreground);overflow-wrap:anywhere';content.append(d);}
 const stem=el('path',{class:'timeline-stem',d:`M${x} 101V116`}),point=el('circle',{class:'timeline-point',cx:x,cy:96,r:7,style:'--timeline-tone:'+tone(t.section)});
 const events=t.events.map((text,j)=>{const e=document.createElement('button');e.type='button';e.className='timeline-event';e.dataset.event=j;e.textContent=text;e.setAttribute('aria-label',[t.section,t.name,text].filter(Boolean).join(' · '));content.append(e);return e;});scene.append(column);const eventPoints=events.map(()=>el('circle',{class:'timeline-event-point',cx:x,cy:116,r:5.5,style:'--timeline-tone:'+tone(t.section)}));objects.push({t,column,b,events,eventPoints,point,stem});});
 const view=createMermaidViewport(root);
 // 完整图收紧列间距，文字在本列内换行，不改事件顺序。
 function layoutMode(){
  gap=view.expanded?24:40;w=view.expanded?184:216;
  const width=left*2+objects.length*(w+gap)-gap;
  root.style.maxWidth=view.expanded?width+'px':'';root.style.marginInline=view.expanded?'auto':'';
  objects.forEach((o,i)=>{o.column.style.width=w+'px';o.column.style.left=left+i*(w+gap)+'px';o.b.style.height='auto';o.b.style.fontSize='13px';});
  const ph=Math.max(38,...objects.map(o=>o.b.offsetHeight));let columnTop=42;
  root.querySelectorAll('.timeline-section').forEach(n=>{const start=Number(n.dataset.sectionIndex);n.style.left=left+start*(w+gap)+'px';n.style.width=Number(n.dataset.sectionCount)*(w+gap)-gap+'px';n.dataset.sectionStart=left+start*(w+gap);n.style.fontSize=view.expanded?'14px':'12px';});
  columnTop=Math.max(42,...[...root.querySelectorAll('.timeline-section')].map(n=>n.offsetHeight+12));const ay=columnTop+12+ph+16;
  objects.forEach((o,i)=>{const x=left+i*(w+gap)+12;o.column.style.top=columnTop+'px';o.b.style.height=ph+'px';o.point.setAttribute('cx',x);o.point.setAttribute('cy',ay);const centers=o.events.map(e=>columnTop+e.offsetTop+e.offsetHeight/2);o.eventPoints.forEach((p,j)=>{p.setAttribute('cx',x);p.setAttribute('cy',centers[j]);});o.stem.setAttribute('d',centers.length?`M${x} ${ay+8}V${centers.at(-1)}`:'');});
  const height=Math.max(180,...objects.map(o=>o.column.offsetHeight+columnTop+24));scene.style.width=scene.style.minWidth=width+'px';scene.style.height=height+'px';svg.style.height=height+'px';svg.setAttribute('viewBox',`0 0 ${width} ${height}`);axis.setAttribute('d',`M${left+12} ${ay}H${left+12+(objects.length-1)*(w+gap)}`);const end=left+12+(objects.length-1)*(w+gap);tail.setAttribute('d',`M${end} ${ay}h120`);fade.setAttribute('x1',end);fade.setAttribute('x2',end+120);fade.setAttribute('y1',ay);fade.setAttribute('y2',ay);[axis,...objects.map(o=>o.stem)].forEach(p=>{p.style.strokeDasharray='none';});view.refresh();
 }
 root.addEventListener('qv:display-mode',()=>{layoutMode();if(!view.expanded)viewport.scrollLeft=view.savedInlinePosition?.left||0;});layoutMode();
 function clear(){root.querySelectorAll('[data-active]').forEach(n=>n.removeAttribute('data-active'));}
 const bind=(b,point)=>{b.onpointerenter=()=>{clear();b.dataset.active='true';if(point)point.dataset.active='true';};b.onpointerleave=()=>{if(!b.matches(':focus-visible')){b.removeAttribute('data-active');if(point)point.removeAttribute('data-active');}};b.onfocus=()=>{clear();b.dataset.active='true';if(point)point.dataset.active='true';const r=b.getBoundingClientRect(),v=viewport.getBoundingClientRect();if(r.left<v.left+12)viewport.scrollLeft-=v.left+12-r.left;else if(r.right>v.right-12)viewport.scrollLeft+=r.right-v.right+12;};b.onblur=()=>{b.removeAttribute('data-active');if(point)point.removeAttribute('data-active');};};objects.forEach(o=>{bind(o.b);o.events.forEach((e,j)=>bind(e,o.eventPoints[j]));});
 // 原生sticky与滚动同步合成，避免scroll事件回写left慢一帧造成边缘抖动。
 viewport.addEventListener('scroll',clear,{passive:true});root.addEventListener('qv:display-mode',clear);root.addEventListener('keydown',e=>{if(e.key==='Escape')clear();});
 const reduced=matchMedia('(prefers-reduced-motion:reduce)');let running=[],armed=true;function replay(){running.forEach(a=>a.cancel());running=[];if(reduced.matches||view.expanded)return;const length=axis.getTotalLength();axis.style.strokeDasharray=`${length} ${length}`;running.push(axis.animate([{strokeDashoffset:length},{strokeDashoffset:0}],{duration:Math.max(480,Math.min(objects.length-1,10)*160),fill:'backwards'}));running.push(tail.animate([{opacity:0},{opacity:1}],{duration:240,delay:Math.min(objects.length-1,10)*160,fill:'backwards'}));objects.forEach((o,i)=>{const delay=Math.min(i,10)*160;running.push(o.column.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,delay,fill:'backwards',easing:'cubic-bezier(.2,.65,.3,1)'}));running.push(o.point.animate([{opacity:0,r:'.32px'},{opacity:1,r:'7px'}],{duration:240,delay,fill:'backwards'}));o.eventPoints.forEach(p=>running.push(p.animate([{opacity:0},{opacity:1}],{duration:240,delay,fill:'backwards'})));const stemLength=o.stem.getTotalLength();o.stem.style.strokeDasharray=`${stemLength} ${stemLength}`;running.push(o.stem.animate([{strokeDashoffset:stemLength},{strokeDashoffset:0}],{duration:240,delay,fill:'backwards'}));});root.dataset.replays=String(+(root.dataset.replays||0)+1);}
 new IntersectionObserver(es=>{if(!es[0].isIntersecting)armed=true;else if(es[0].intersectionRatio>=.2&&armed){armed=false;replay()}},{threshold:[0,.2]}).observe(root);document.addEventListener('visibilitychange',()=>{if(document.hidden)armed=true;else if(armed){armed=false;replay()}});root.addEventListener('qv:display-mode',()=>running.forEach(a=>a.cancel()));reduced.addEventListener('change',()=>running.forEach(a=>a.cancel()));view.refresh();
}
